            ("Score de Saude",       "Ranking 0-100"),
            ("GMD Temporal",         "Evolucao no tempo"),
            ("Comparativo Lotes",    "Side by side"),
            ("Painel de Decisao",    "Lucro por lote"),
            ("Dashboard Executivo",  "KPIs do lote"),
